      const fromIds = this.activeScopes.map((s) => scopedId(s, source));
      const toIds = this.activeScopes.map((s) => scopedId(s, target));
      const fromPh = fromIds.map(() => "?").join(",");
      const toPh = toIds.map(() => "?").join(",");
